mapper.sql:
WHERE w.user_id = #{userId}

    AND wc.workplace_id = #{workplaceId}


    AND wt.created_at >= #{from}


    AND wt.created_at < #{toExclusive}


    AND wt.transaction_type = #{type}


    AND wt.amount >= #{minAmount}


    AND wt.amount <= #{maxAmount}


    AND wc.title LIKE CONCAT('%', #{keyword}, '%')

mapper.select:
SELECT wt.id AS transactionId, wt.transaction_type AS type, wt.amount AS amount, wt.available_after AS availableAfter, wt.locked_after AS lockedAfter, wt.work_case_id AS workCaseId, wc.title AS workTitle, wp.name AS workplaceName, wt.created_at AS createdAt FROM wallet_transactions wt JOIN wallets w ON w.id = wt.wallet_id LEFT JOIN work_cases wc ON wc.id = wt.work_case_id LEFT JOIN workplaces wp ON wp.id = wc.workplace_id
ORDER BY wt.id ASC ORDER BY wt.amount ASC, wt.id DESC ORDER BY wt.amount DESC, wt.id DESC ORDER BY wt.id DESC
LIMIT #{size} OFFSET #{offset}
